<?php
declare(strict_types=1);
namespace App\Application\Services;
use App\Core\Persistence\Connection;
use App\Domain\Catalog\{Product,ProductVariant};
use PDO;
final class CatalogImportService
{
    public const HEADERS=['product_code','product_name','description','category_code','brand_code','sku','variant_name','unit_code'];
    public function __construct(private readonly Connection$connection,private readonly string$directory){}
    public function template():string{return implode(',',self::HEADERS)."\r\n";}
    public function preview(string$path,string$name,int$size,int$actor):array
    {
        if($size<1||$size>2097152||strtolower(pathinfo($name,PATHINFO_EXTENSION))!=='csv'||!is_uploaded_file($path))throw new \InvalidArgumentException('Selecciona un CSV UTF-8 válido de hasta 2 MB.');
        $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($mime,['text/plain','text/csv','application/csv','application/vnd.ms-excel'],true))throw new \InvalidArgumentException('El contenido no corresponde a un archivo CSV.');
        $handle=fopen($path,'rb');if(!$handle)throw new \InvalidArgumentException('No se pudo leer el archivo.');$header=fgetcsv($handle,0,',','"','\\');if(isset($header[0]))$header[0]=preg_replace('/^\xEF\xBB\xBF/','',(string)$header[0]);if($header!==self::HEADERS){fclose($handle);throw new \InvalidArgumentException('Las columnas no coinciden con la plantilla oficial.');}
        $raw=[];$line=1;while(($values=fgetcsv($handle,0,',','"','\\'))!==false){$line++;if(count($values)===1&&trim((string)$values[0])==='')continue;if(count($raw)>=1000){fclose($handle);throw new \InvalidArgumentException('El archivo admite hasta 1,000 filas de datos.');}if(count($values)!==count(self::HEADERS)){$raw[]=['line'=>$line,'data'=>[],'errors'=>['La fila no contiene las ocho columnas.']];continue;}$raw[]=['line'=>$line,'data'=>array_combine(self::HEADERS,array_map(static fn($v)=>trim((string)$v),$values)),'errors'=>[]];}fclose($handle);if(!$raw)throw new \InvalidArgumentException('El archivo no contiene productos.');
        $analysis=$this->analyze($raw);if(!is_dir($this->directory)&&!mkdir($this->directory,0700,true)&&!is_dir($this->directory))throw new \RuntimeException('No se pudo preparar el almacenamiento privado.');foreach(glob($this->directory.'/*.json')?:[]as$old)if(is_file($old)&&filemtime($old)<time()-86400)@unlink($old);$token=bin2hex(random_bytes(24));$record=['token'=>$token,'actor'=>$actor,'expires'=>time()+1800,'status'=>'preview','rows'=>$raw,'hash'=>hash('sha256',json_encode($raw,JSON_THROW_ON_ERROR))];$target=$this->directory.'/'.$token.'.json';if(file_put_contents($target,json_encode($record,JSON_THROW_ON_ERROR),LOCK_EX)===false)throw new \RuntimeException('No se pudo conservar la vista previa.');chmod($target,0600);return['token'=>$token]+$analysis;
    }
    public function confirm(string$token,int$actor):array
    {
        if(!preg_match('/^[a-f0-9]{48}$/D',$token))throw new \InvalidArgumentException('La vista previa no es válida.');$path=$this->directory.'/'.$token.'.json';$handle=@fopen($path,'c+');if(!$handle||!flock($handle,LOCK_EX|LOCK_NB))throw new \InvalidArgumentException('La importación ya está siendo confirmada.');try{$json=stream_get_contents($handle);$record=json_decode($json?:'',true,512,JSON_THROW_ON_ERROR);if(($record['actor']??0)!==$actor||($record['expires']??0)<time())throw new \InvalidArgumentException('La vista previa caducó; analiza nuevamente el archivo.');if(($record['status']??'')!=='preview')throw new \InvalidArgumentException('La importación ya fue confirmada.');if(!hash_equals((string)$record['hash'],hash('sha256',json_encode($record['rows'],JSON_THROW_ON_ERROR))))throw new \InvalidArgumentException('La vista previa fue alterada.');$analysis=$this->analyze($record['rows']);if($analysis['rejected']>0)throw new \InvalidArgumentException('Corrige todas las filas rechazadas antes de confirmar.');$created=$this->connection->transaction(function(PDO$pdo)use($analysis):int{$count=0;foreach($analysis['rows']as$row){$d=$row['data'];$category=$this->catalogId($pdo,'categories',$d['category_code'],false);$brand=$d['brand_code']===''?null:$this->catalogId($pdo,'brands',$d['brand_code'],false);$unit=$this->catalogId($pdo,'units',$d['unit_code'],false);$s=$pdo->prepare('INSERT INTO products(code,name,description,category_id,brand_id,tracks_lots,tracks_expiration,tracks_serials,is_active) VALUES(?,?,?,?,?,0,0,0,0)');$s->execute([$d['product_code'],$d['product_name'],$d['description']===''?null:$d['description'],$category,$brand]);$product=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO product_variants(product_id,unit_id,sku,name,is_active) VALUES(?,?,?,?,0)');$s->execute([$product,$unit,$d['sku'],$d['variant_name']]);$count++;}return$count;});$record['status']='confirmed';$record['confirmed_at']=time();$record['created']=$created;ftruncate($handle,0);rewind($handle);fwrite($handle,json_encode($record,JSON_THROW_ON_ERROR));fflush($handle);return['created'=>$created];}finally{flock($handle,LOCK_UN);fclose($handle);}}
    private function analyze(array$raw):array
    {
        $pdo=$this->connection->pdo();$seenCode=[];$seenSku=[];$out=[];$accepted=0;
        foreach($raw as$row){$errors=$row['errors'];$d=$row['data'];if($d){try{$product=Product::create($d['product_code'],$d['product_name'],$d['description']===''?null:$d['description'],1,null,false,false,false);$variant=ProductVariant::create(1,1,$d['sku'],$d['variant_name']);$d['product_code']=$product->code;$d['sku']=$variant->sku;}catch(\InvalidArgumentException$e){$errors[]=$e->getMessage();}foreach(['category_code'=>'La categoría','unit_code'=>'La unidad']as$key=>$label)if($d[$key]===''||!preg_match('/^[A-Z0-9][A-Z0-9_-]{0,63}$/D',$d[$key]))$errors[]=$label.' no es válida.';if($d['brand_code']!==''&&!preg_match('/^[A-Z0-9][A-Z0-9_-]{0,63}$/D',$d['brand_code']))$errors[]='La marca no es válida.';if(isset($seenCode[$d['product_code']]))$errors[]='Clave de producto duplicada en el archivo.';if(isset($seenSku[$d['sku']]))$errors[]='SKU duplicado en el archivo.';$seenCode[$d['product_code']]=true;$seenSku[$d['sku']]=true;if($this->exists($pdo,'products','code',$d['product_code']))$errors[]='La clave de producto ya existe.';if($this->exists($pdo,'product_variants','sku',$d['sku']))$errors[]='El SKU ya existe.';foreach([['categories',$d['category_code'],'La categoría'],['units',$d['unit_code'],'La unidad'],['brands',$d['brand_code'],'La marca']]as[$table,$code,$label])if($code!==''&&!$this->exists($pdo,$table,'code',$code,true))$errors[]=$label.' no existe o está inactiva.';}$errors=array_values(array_unique($errors));if(!$errors)$accepted++;$out[]=['line'=>$row['line'],'data'=>$d,'errors'=>$errors];}
        return['rows'=>$out,'accepted'=>$accepted,'rejected'=>count($out)-$accepted,'total'=>count($out)];
    }
    private function exists(PDO$pdo,string$table,string$field,string$value,bool$active=false):bool{$s=$pdo->prepare("SELECT id FROM $table WHERE $field=?".($active?' AND is_active=1':'').' LIMIT 1');$s->execute([$value]);return$s->fetchColumn()!==false;}
    private function catalogId(PDO$pdo,string$table,string$code,bool$lock):int{$s=$pdo->prepare("SELECT id FROM $table WHERE code=? AND is_active=1".($lock?' FOR UPDATE':''));$s->execute([$code]);$id=$s->fetchColumn();if($id===false)throw new \InvalidArgumentException('Un catálogo relacionado cambió desde la vista previa.');return(int)$id;}
}
